from pathlib import Path
from fastapi.testclient import TestClient

def test_v1_end_to_end_and_replay(tmp_path:Path,monkeypatch):
 monkeypatch.setenv('DATABASE_URL',f"sqlite:///{tmp_path/'v1.db'}"); from dataset_api.dependencies.repository import get_service; get_service.cache_clear(); from dataset_api.main import app; client=TestClient(app)
 created=client.post('/api/v1/datasets',json={'name':'release-e2e','description':'v1'}); assert created.status_code==201; did=created.json()['id']
 version=client.post(f'/api/v1/datasets/{did}/versions',json={'records':[{'id':1,'name':' Alice ','score':10},{'id':2,'name':'Bob','score':20},{'id':3,'name':'Bob','score':20}],'schema':{'fields':[{'name':'id','data_type':'integer','required':True,'nullable':False},{'name':'name','data_type':'string','required':True,'nullable':False},{'name':'score','data_type':'integer','required':True,'nullable':False}]}}); assert version.status_code==201
 assert client.post(f'/api/v1/datasets/{did}/validate').status_code==200; assert client.post(f'/api/v1/datasets/{did}/quality').status_code==200; assert client.post(f'/api/v1/datasets/{did}/deduplicate',json={}).status_code==200
 run_id=client.post(f'/api/v1/datasets/{did}/transform',json={'normalize_fields':['name']}).json()['run']['id']; assert client.get(f'/api/v1/runs/{run_id}').status_code==200; assert client.post(f'/api/v1/datasets/{did}/sample',json={'size':2,'seed':42}).status_code==200; assert client.post(f'/api/v1/datasets/{did}/split',json={'train':.8,'validation':.1,'test':.1,'seed':42}).status_code==200; assert client.post(f'/api/v1/datasets/{did}/evaluate',json={}).status_code==200
 replay=client.get(f'/api/v1/runs/{run_id}/replay'); assert replay.status_code==200 and replay.json()['status']=='REPRODUCIBLE' and replay.json()['output_fingerprint_matches'] is True; provenance=client.get(f'/api/v1/datasets/{did}/provenance'); assert provenance.status_code==200 and len(provenance.json()['versions'])>=2 and len(provenance.json()['runs'])>=4; audit=client.get(f'/api/v1/datasets/{did}/audit'); assert audit.status_code==200 and audit.json() and all(e['event_hash'] for e in audit.json())

def test_v1_failure_paths(tmp_path:Path,monkeypatch):
 monkeypatch.setenv('DATABASE_URL',f"sqlite:///{tmp_path/'fail.db'}"); from dataset_api.dependencies.repository import get_service; get_service.cache_clear(); from dataset_api.main import app; client=TestClient(app)
 assert client.post('/api/v1/datasets',json={'name':'bad name'}).status_code==422; assert client.get('/api/v1/datasets/00000000-0000-0000-0000-000000000000').status_code==404; assert client.post('/api/v1/datasets',json={'name':'safe'}).status_code==201; did=client.get('/api/v1/datasets').json()[0]['id']; assert client.post(f'/api/v1/datasets/{did}/versions',json={'records':[{'id':1}],'schema':{}}).status_code==201; assert client.post(f'/api/v1/datasets/{did}/sample',json={'size':999999999}).status_code==422; assert client.post(f'/api/v1/datasets/{did}/split',json={'train':.8,'validation':.8,'test':.1}).status_code==422; assert client.get('/api/v1/runs/00000000-0000-0000-0000-000000000000/replay').status_code==404
